  const facts:[Key,unknown][]=[["observed",date(c.observedAt)],["lastPass",date(c.lastPassedAt)],...(c.failedAt?[["failedAt",date(c.failedAt)] as [Key,unknown]]:[]),["evidenceTime",date(c.evidenceAt)],["value",c.value??"—"],["threshold",c.threshold??"—"],["failures",c.failures],["successes",c.successes]];
  modal(`${dialogHead(c.name,`${host} · ${c.app}`,sym(i,tint,"large"))}<div class="dialog-body"><div class="status-line">${badge(s)}<span>${t(c.coverage)}${muted?` · ${t("muted")}`:""}</span></div>${s==="transient"?`<p class="note">${icon("info")}${t("transientHint")}</p>`:""}<div class="group-title"><h2>${t("evidence")}</h2></div><div class="list"><div class="evidence"><code>${esc(c.code)}</code><p>${esc(c.detail)}</p></div></div><div class="list facts">${facts.map(([k,v])=>`<div class="row static"><span class="row-main">${t(k)}</span><span class="value">${esc(v)}</span></div>`).join("")}</div><div class="group-title"><h2>${t("history")}</h2></div><div class="card probe-history" id="probe-history"><span class="muted">${t("noHistory")}</span></div><p class="group-foot">${t(c.remote?"readOnly":rule?"ruleHint":"automaticHint")}</p>${c.kind==="task"&&!c.remote?policyForm(id.slice(5)):""}${c.remote?"":`<div class="dialog-actions"><button class="button secondary" id="toggle-check">${t(c.enabled?"pause":"resume")}</button><button class="button secondary" id="mute-check">${t(muted?"unmute":"mute")}</button>${openIncident?`<button class="button secondary" id="view-incident">${t("viewIncident")}</button>`:`<button class="button secondary" id="new-incident-check">${t("createIncident")}</button>`}${rule?`<button class="button primary" id="edit-rule">${t("edit")}</button>`:""}</div>`}</div>`,true);
